UPDATE wms_inventory
SET qty = qty + #{qty}, update_time = CURRENT_TIMESTAMP
WHERE inventory_id = #{inventoryId}

UPDATE wms_inventory
SET qty = qty - #{qty}, update_time = CURRENT_TIMESTAMP
WHERE inventory_id = #{inventoryId} AND qty >= #{qty}
